func (r *agentRunResolver) Definition(ctx context.Context, obj *agent.AgentRun) (*agentdefinition.Definition, error) {
	if obj.AgentDefinitionID.IsNil() {
		return nil, nil
	}

	l, ok := loaders.FromContext(ctx)
	if !ok {
		return nil, nil
	}

	definition, err := l.AgentDefinitionByID.Load(ctx, obj.AgentDefinitionID.String())
	if err != nil {
		// A run of a retired built-in agent names a definition that is gone;
		// the run is still worth showing.
		if errortypes.IsNotFoundError(err) {
			return nil, nil
		}

		return nil, err
	}

	return definition, nil
}

